// Cuenta intercambios de la sesion (columna tecnica de soporte,
// no forma parte de los 5 campos de negocio fijos del brief).
const previo = Number($('Preparar Contexto Previo').item.json.memoria_intercambios) || 0;
return [{
  json: {
    ...$json,
    intercambios_actualizados: previo + 1
  }
}];

// Solo se ejecuta cuando se superan los 5 intercambios. Convierte el
// JSON estructurado del Summarizer en un texto breve, y resetea el
// contador a 0 (Paso 8 del brief: sobreescribe, no acumula).
const r = $json.output;
const previo = $('Incrementar Contador de Intercambios').item.json;
const resumenTexto = 'Asunto: ' + r.asunto_principal + ' | Puntos clave: ' + (r.puntos_clave || []).join('; ') + ' | Acción requerida: ' + r.accion_requerida;
return [{
  json: {
    ...previo,
    resumen_para_guardar: resumenTexto,
    intercambios_para_guardar: 0
  }
}];

// Todavia no se supero el umbral: se guarda el resultado de ESTE
// turno tal cual (sin consolidar todavia), y el contador sigue sumando.
return [{
  json: {
    ...$json,
    resumen_para_guardar: $json.output,
    intercambios_para_guardar: $json.intercambios_actualizados
  }
}];
